"""
Paper Trading Skill Module for A-Share Market

This module provides a complete paper trading simulation engine for A-share stocks,
implementing realistic trading mechanics, position management, and backtesting capabilities.

Classes:
    PaperTradingEngine: Manages virtual portfolio with T+1 settlement
    MomentumValueStrategy: Implements momentum-value hybrid strategy
    BacktestRunner: Runs strategy against historical data
"""

import os
import sys
import json
import csv
from datetime import datetime, timedelta
from typing import Dict, List, Any, Optional, Tuple, Union
from dataclasses import dataclass, field
from enum import Enum
from decimal import Decimal
import statistics

import pandas as pd
import numpy as np

@dataclass
class TradingFeeConfig:
    """A-share trading fee configuration"""
    market: str = "A-share"
    currency: str = "CNY"
    commission_rate: float = 0.00025
    commission_min_amount: float = 5.0
    stamp_tax_rate: float = 0.001
    transfer_fee_rate: float = 0.00002

    def calculate_commission(self, trade_amount: float, is_buy: bool) -> float:
        commission = trade_amount * self.commission_rate
        return max(commission, self.commission_min_amount)

    def calculate_stamp_tax(self, trade_amount: float, is_buy: bool) -> float:
        if is_buy:
            return 0.0
        return trade_amount * self.stamp_tax_rate

    def calculate_transfer_fee(self, trade_amount: float) -> float:
        return trade_amount * self.transfer_fee_rate

    def calculate_total_cost(self, trade_amount: float, is_buy: bool) -> float:
        commission = self.calculate_commission(trade_amount, is_buy)
        stamp_tax = self.calculate_stamp_tax(trade_amount, is_buy)
        transfer_fee = self.calculate_transfer_fee(trade_amount)
        total = commission + stamp_tax + transfer_fee
        return round(total, 2)

    def calculate_execution_cost(self, trade_amount: float, is_buy: bool) -> float:
        if is_buy:
            return self.calculate_commission(trade_amount, is_buy) + self.calculate_transfer_fee(trade_amount)
        else:
            return self.calculate_commission(trade_amount, is_buy) + self.calculate_stamp_tax(trade_amount, is_buy) + self.calculate_transfer_fee(trade_amount)

