class TradingCalendar:
    def __init__(self, holidays_path: str):
        self.holidays = set()
        self.load_holidays(holidays_path)

    def load_holidays(self, path: str):
        if not os.path.exists(path):
            return
        df = pd.read_csv(path)
        for _, row in df.iterrows():
            date = row[\"date\"]
            htype = row[\"type\"]
            if htype not in [\"makeup_workday\", \"regular_workday\", \"public_holiday\", \"spring_festival\", \"qingming\", \"tomb_sweeping\", \"dragon_boat\", \"mid_autumn\", \"national_day\", \"christmas\", \"labour_day\", \"youth_day\"]:
                self.holidays.add(date)

    def is_trading_day(self, date: str) -> bool:
        if date in self.holidays:
            return False
        try:
            day = datetime.strptime(date, \"%Y-%m-%d\").weekday()
            if day in [5, 6]:
                return False
        except:
            pass
        return True

    def get_trading_days(self, start_date: str, end_date: str) -> List[str]:
        start = datetime.strptime(start_date, \"%Y-%m-%d\")
        end = datetime.strptime(end_date, \"%Y-%m-%d\")
        days = []
        cur = start
        while cur <= end:
            dstr = cur.strftime(\"%Y-%m-%d\")
            if dstr not in self.holidays and cur.weekday() < 5:
                days.append(dstr)
            cur += timedelta(days=1)
        return days
